action.command:
node -e "
const path = require('path');
const { execSync } = require('child_process');
const file = JSON.parse(require('fs').readFileSync('/dev/stdin','utf8')).file || '';
const isPy = file.endsWith('.py');
const isTs = file.endsWith('.ts') || file.endsWith('.tsx');
try {
  if (isPy) {
    execSync('ruff check ' + file, {cwd: process.env.WORKSPACE_ROOT || '.', stdio:'pipe'});
    execSync('black --check ' + file, {cwd: process.env.WORKSPACE_ROOT || '.', stdio:'pipe'});
    execSync('mypy --strict ' + file, {cwd: process.env.WORKSPACE_ROOT || '.', stdio:'pipe'});
    console.log('Python lint/format/typecheck passed: ' + file);
  } else if (isTs) {
    execSync('npx eslint ' + file, {cwd: (process.env.WORKSPACE_ROOT || '.') + '/frontend', stdio:'pipe'});
    execSync('npx prettier --check ' + file, {cwd: (process.env.WORKSPACE_ROOT || '.') + '/frontend', stdio:'pipe'});
    console.log('TS lint/format passed: ' + file);
  }
} catch(e) { process.stderr.write(e.stdout ? e.stdout.toString() : e.message); process.exit(2); }
"
